<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();$flashes=render_flashes();$currentPage='decisions';$pageTitle='My Decisions';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$rows=[];if($uid<=0){http_response_code(403);exit('Invalid Assessor account.');}if(as_has_table($conn,'assessment_decisions')){$s=$conn->prepare("SELECT ad.*,aa.attempt_number,u.first_name,u.last_name,u.email,ao.code outcome_code,ao.title outcome_title,ac.code criterion_code,ac.title criterion_title,ae.title evidence_title FROM assessment_decisions ad JOIN assessment_attempts aa ON aa.id=ad.attempt_id JOIN users u ON u.id=aa.participant_id JOIN assessment_outcomes ao ON ao.id=aa.outcome_id JOIN assessment_criteria ac ON ac.id=ad.criterion_id LEFT JOIN assessment_evidence ae ON ae.id=ad.evidence_id WHERE ad.assessor_id=? ORDER BY ad.updated_at DESC LIMIT 250");if($s){$s->bind_param('i',$uid);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}}require __DIR__.'/_layout_start.php';?>
<div class="as-page-header"><div><span class="as-page-header__eyebrow">Assessment History</span><h2>My Decisions</h2><p>A complete criterion-level history of decisions you have recorded.</p></div></div><div class="as-card"><div class="as-card__header"><div><h3>Decision Register</h3><p><?= count($rows) ?> decision(s).</p></div></div><?php if(!$rows):?><div class="as-empty"><div class="as-empty__icon"><i class="fas fa-gavel"></i></div><strong>No decisions recorded</strong><span>Criterion-level decisions will appear here.</span></div><?php else:?><div class="as-table-wrap"><table class="as-table"><thead><tr><th>Participant</th><th>Outcome</th><th>Criterion</th><th>Result</th><th>Evidence</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><strong><?= e(trim($x['first_name'].' '.$x['last_name'])) ?></strong><span class="as-table-sub"><?= e($x['email']) ?></span></td><td><strong><?= e($x['outcome_code']) ?></strong><span class="as-table-sub"><?= e($x['outcome_title']) ?></span></td><td><strong><?= e($x['criterion_code']) ?></strong><span class="as-table-sub"><?= e($x['criterion_title']) ?></span></td><td><span class="as-status as-status--<?= e(as_class($x['result'])) ?>"><?= e(as_label($x['result'])) ?></span></td><td><?= e($x['evidence_title']?:'—') ?></td><td><?= e(as_datetime($x['updated_at'])) ?></td><td class="as-table__action"><a class="as-icon-btn" href="<?= url('assessor/review_assessment.php?id='.(int)$x['attempt_id']) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require __DIR__.'/_layout_end.php';?>
